                (Some(anchor_attribute), _) => {
                    if anchor_attribute
                        .as_html_attribute()
                        .is_some_and(|attr| attr.initializer().is_none())
                    {
                        return Some(UseValidAnchorState::IncorrectHref(anchor_attribute.range()));
                    }

